class Solution {
    unordered_map<TreeNode*, TreeNode*> parent;
    TreeNode* target = nullptr;

    void build(TreeNode* node, TreeNode* prev, int k) {
        if (!node) {
            return;
        }
        parent[node] = prev;
        if (node->val == k) {
            target = node;
        }
        build(node->left, node, k);
        build(node->right, node, k);
    }

public:
    int findClosestLeaf(TreeNode* root, int k) {
        parent.clear();
        target = nullptr;
        build(root, nullptr, k);
        queue<TreeNode*> q;
        unordered_set<TreeNode*> seen;
        q.push(target);
        seen.insert(target);
        while (!q.empty()) {
            TreeNode* node = q.front();
            q.pop();
            if (!node->left && !node->right) {
                return node->val;
            }
            for (TreeNode* next : {node->left, node->right, parent[node]}) {
                if (next && seen.insert(next).second) {
                    q.push(next);
                }
            }
        }
        return -1;
    }
};
